sql.where:
a.deleted_at IS NULL

AND drafter.company_id = #{companyId}
AND a.user_id = #{drafterId}
AND a.status = #{status}
AND a.created_at >= #{fromDate}
AND a.created_at < DATE_ADD(#{toDate}, INTERVAL 1 DAY)
AND a.current_revision_no = #{revisionNo}

    AND (cr.title LIKE CONCAT('%', #{keyword}, '%') OR proj.name LIKE CONCAT('%', #{keyword}, '%'))


    AND EXISTS (
        SELECT 1 FROM approval_line l
        WHERE l.approval_revision_id = cr.approval_revision_id
            AND l.user_id = #{approverId}
            AND l.deleted_at IS NULL
    )


    AND EXISTS (
        SELECT 1 FROM approval_line l
        WHERE l.approval_revision_id = cr.approval_revision_id
            AND l.user_id = #{activeApproverId}
            AND l.status = 'ACTIVE'
            AND l.deleted_at IS NULL
    )

mapper.select:
SELECT a.approval_id AS approvalId, cr.title AS title, a.status AS status, a.current_revision_no AS currentRevisionNo, cr.approval_revision_id AS currentRevisionId, a.user_id AS drafterId, drafter.name AS drafterName, ca.user_id AS currentApproverId, capp.name AS currentApproverName, proj.project_id AS projectId, proj.name AS projectName, st.step_id AS stepId, st.name AS stepName, a.created_at AS createdAt, cr.submitted_at AS submittedAt, a.completed_at AS completedAt
LEFT JOIN approval_line ca ON ca.approval_revision_id = cr.approval_revision_id AND ca.status = 'ACTIVE' AND ca.deleted_at IS NULL LEFT JOIN employee capp ON capp.user_id = ca.user_id
ORDER BY a.created_at DESC, a.approval_id DESC LIMIT #{limit} OFFSET #{offset}
